corpus_block("test-stat-density.R: stat_density actually computes density", {
  dens <- stats::density(mtcars$mpg)
  expected_density_fun <- stats::approxfun(data.frame(x = dens$x, y = dens$y))
  .plot("test-stat-density.R: stat_density actually computes density #1", plot <- ggplot(mtcars, aes(mpg)) + stat_density())
  actual_density_fun <- stats::approxfun(get_layer_data(plot)[, c("x", "y")])
  test_sample <- unique(mtcars$mpg)
})

corpus_block("test-stat-density.R: stat_density can make weighted density estimation", {
  df <- mtcars
  df$weight <- mtcars$cyl
  dens <- stats::density(
      df$mpg, weights = df$weight / sum(df$weight),
      bw = stats::bw.nrd0(df$mpg)
    )
  expected_density_fun <- stats::approxfun(data.frame(x = dens$x, y = dens$y))
  .plot("test-stat-density.R: stat_density can make weighted density estimation #1", ggplot(df, aes(mpg, weight = weight)) + stat_density())
  plot <- get_layer_data(ggplot(df, aes(mpg, weight = weight)) + stat_density())
  actual_density_fun <- stats::approxfun(plot[, c("x", "y")])
  test_sample <- unique(df$mpg)
})

corpus_block("test-stat-density.R: stat_density handles data outside of `bounds`", {
  cutoff <- mtcars$mpg[1]
  .plot("test-stat-density.R: stat_density handles data outside of `bounds` #1", ggplot(mtcars, aes(mpg, weight = cyl)) + stat_density(bounds = c(cutoff, Inf)))
